tool_input.command:
$base = "http://zentao-biz.zhi.com"
$body = @{ account='tiany'; password='Field123456' } | ConvertTo-Json
try {
  $r = Invoke-WebRequest -Uri "$base/api.php/v1/tokens" -Method Post -Body $body -ContentType 'application/json' -UseBasicParsing
  $tok = ($r.Content | ConvertFrom-Json).token
  $hd = @{ 'Token' = $tok; 'Accept' = 'application/json' }
  $r2 = Invoke-WebRequest -Uri "$base/api.php/v1/files/21469" -Headers $hd -UseBasicParsing
  $bytes = $r2.RawContentStream.ToArray()
  [IO.File]::WriteAllBytes("D:\repository\苏州市房地产监测V3\bug6155.png", $bytes)
  Write-Output "OK bytes=$($bytes.Length) head=$($bytes[0]),$($bytes[1])"
} catch { Write-Output "ERR: $($_.Exception.Message)" }
